1	package org.springframework.samples.petclinic.mapper;
2	
3	import org.jspecify.annotations.NonNull;
4	import org.mapstruct.Mapper;
5	import org.mapstruct.Mapping;
6	import org.springframework.beans.factory.annotation.Autowired;
7	import org.springframework.data.domain.Page;
8	import org.springframework.samples.petclinic.model.Owner;
9	import org.springframework.samples.petclinic.rest.controller.CityRegionResolver;
10	import org.springframework.samples.petclinic.rest.controller.TelephoneNormalizer;
11	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
12	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
13	import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;
14	import org.springframework.samples.petclinic.service.ClinicService;
15	import org.springframework.samples.petclinic.util.HashUtils;
16	import org.springframework.samples.petclinic.util.IdentityUtils;
17	
18	import java.time.LocalDate;
19	import java.time.Month;
20	import java.time.Period;
21	import java.util.Collection;
22	import java.util.List;
23	import java.util.Locale;
24	import java.util.OptionalInt;
25	
26	/**
27	 * Maps Owner & OwnerDto using Mapstruct
28	 */
29	@Mapper(uses = PetMapper.class)
30	public abstract class OwnerMapper {
31	
32	    /** Used to count the members of an owner's household when deriving derived fields. */
33	    @Autowired
34	    protected ClinicService clinicService;
35	
36	    /** Single source of truth for the city-to-region mapping behind an owner's locality. */
37	    @Autowired
38	    protected CityRegionResolver cityRegionResolver;
39	
40	    /** Formats the stored E.164 telephone into its human-readable display form. */
41	    @Autowired
42	    protected TelephoneNormalizer telephoneNormalizer;
43	
44	    @Mapping(target = "selfLink", expression = "java(selfLink(owner))")
45	    @Mapping(target = "salutation", expression = "java(salutation(owner))")
46	    @Mapping(target = "displayName",
47	        expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
48	    @Mapping(target = "initials", expression = "java(initials(owner))")
49	    @Mapping(target = "membershipPoints", expression = "java(membershipPoints(owner))")
50	    @Mapping(target = "membershipLevel", expression = "java(membershipLevel(owner))")
51	    @Mapping(target = "locality", expression = "java(locality(owner))")
52	    @Mapping(target = "timezone", expression = "java(timezone(owner))")
53	    @Mapping(target = "contactPreference", expression = "java(contactPreference(owner))")
54	    @Mapping(target = "telephoneDisplay", expression = "java(telephoneNormalizer.toDisplayForm(owner.getTelephone()))")
55	    @Mapping(target = "identityKey", expression = "java(identityKey(owner))")
56	    @Mapping(target = "ageBand", expression = "java(ageBand(owner))")
57	    @Mapping(target = "ownerSegment", expression = "java(ownerSegment(owner))")
58	    @Mapping(target = "fiscalYear", expression = "java(fiscalYear(owner))")
59	    public abstract OwnerDto toOwnerDto(Owner owner);
60	
61	    /**
62	     * The owner's self link: '/api/owners/' followed by the owner's id, or null when the
63	     * owner has no id assigned yet.
64	     */
65	    String selfLink(Owner owner) {
66	        return owner.getId() == null ? null : "/api/owners/" + owner.getId();
67	    }
68	
69	    /**
70	     * The fiscal year (starting 1 July) that {@code date} falls in, identified by the
71	     * calendar year in which the fiscal year ends: a date in July–December belongs to the
72	     * fiscal year ending the following calendar year, while January–June belongs to the one
73	     * ending that same calendar year.
74	     */
75	    public static int fiscalYear(LocalDate date) {
76	        return date.getMonthValue() >= Month.JULY.getValue() ? date.getYear() + 1 : date.getYear();
77	    }
78	
79	    /**
80	     * The owner's fiscal year formatted 'FY<YY>', where YY is the two-digit FY segment carried by
81	     * the owner's assigned memberId (see {@link #memberIdCore}). When no memberId has been assigned
82	     * this falls back to the fiscal year of the (business-day-adjusted) {@code registrationDate}
83	     * (the fiscal year starts on 1 July), and returns null when there is no registrationDate either.
84	     */
85	    String fiscalYear(Owner owner) {
86	        String core = memberIdCore(owner.getMemberId());
87	        if (core != null && core.length() > 11) {
88	            return "FY" + core.substring(core.length() - 11, core.length() - 9);
89	        }
90	        LocalDate registrationDate = owner.getRegistrationDate();
91	        if (registrationDate == null) {
92	            return null;
93	        }
94	        return String.format("FY%02d", fiscalYear(registrationDate) % 100);
95	    }
96	
97	    /**
98	     * The owner's age band derived from {@code birthDate} relative to the
99	     * {@code registrationDate}: 'MINOR' when under 18, 'ADULT' from 18 to 64
100	     * inclusive and 'SENIOR' at 65 or older. Returns null when either date is
101	     * absent so no band can be computed.
102	     */
103	    OwnerDto.AgeBandEnum ageBand(Owner owner) {
104	        LocalDate birthDate = owner.getBirthDate();
105	        LocalDate registrationDate = owner.getRegistrationDate();
106	        if (birthDate == null || registrationDate == null) {
107	            return null;
108	        }
109	        int age = Period.between(birthDate, registrationDate).getYears();
110	        if (age < 18) {
111	            return OwnerDto.AgeBandEnum.MINOR;
112	        }
113	        if (age < 65) {
114	            return OwnerDto.AgeBandEnum.ADULT;
115	        }
116	        return OwnerDto.AgeBandEnum.SENIOR;
117	    }
118	
119	    /**
120	     * The Luhn check digit (0-9) over the digits contained in {@code s}: from the rightmost
121	     * digit leftward, every second digit is doubled (the rightmost first) with digits over 9
122	     * reduced by 9, and the check digit makes the total a multiple of ten.
123	     *
124	     * <p>This is the single Luhn derivation behind the application's identity values; like
125	     * {@link #fiscalYear(LocalDate)} and {@link #identityKey(Owner)} it is exposed so the check
126	     * digit is computed the one way wherever an identifier is assembled, including outside this
127	     * package.
128	     */
129	    public static int luhn(String s) {
130	        int sum = 0;
131	        boolean doubling = true;
132	        for (int i = s.length() - 1; i >= 0; i--) {
133	            char c = s.charAt(i);
134	            if (c < '0' || c > '9') {
135	                continue;
136	            }
137	            int d = c - '0';
138	            if (doubling) {
139	                d *= 2;
140	                if (d > 9) {
141	                    d -= 9;
142	                }
143	            }
144	            sum += d;
145	            doubling = !doubling;
146	        }
147	        return (10 - (sum % 10)) % 10;
148	    }
149	
150	    /**
151	     * The owner's derived identity key: the SHA-256 hex digest of the normalized telephone,
152	     * the lower-cased email (or an empty string when absent) and the {@link IdentityUtils#soundex
153	     * soundex} of the last name, joined by '|'. This single key is the sole basis for duplicate
154	     * detection on create — two owners are duplicates only when their whole identityKey matches,
155	     * so two people sharing a household (a like-sounding last name and postcode) but carrying
156	     * different telephones derive different keys and are all permitted.
157	     */
158	    public static String identityKey(Owner owner) {
159	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
160	        String email = owner.getEmail() == null ? "" : owner.getEmail().toLowerCase(Locale.ROOT);
161	        String lastNameSoundex = IdentityUtils.soundex(owner.getLastName());
162	        return HashUtils.sha256Hex(telephone + "|" + email + "|" + lastNameSoundex);
163	    }
164	
165	    /**
166	     * The owner's preferred contact channel: 'EMAIL' when an email address is
167	     * present, otherwise 'PHONE'.
168	     */
169	    String contactPreference(Owner owner) {
170	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
171	        return hasEmail ? "EMAIL" : "PHONE";
172	    }
173	
174	    /**
175	     * The memberId's core: the {@code '<REGION><FY><HASH8><CHK>'} carried by the owner's assigned
176	     * memberId, with any de-duplication {@code '-<n>'} suffix stripped, or null when no memberId has
177	     * been assigned. This is the single place the stored identifier is split back into its fixed
178	     * segments (a trailing FY of 2, HASH8 of 8 and CHK of 1 — eleven characters — following the
179	     * variable-length region), so every rule keyed on a segment reads it the one way.
180	     */
181	    private static String memberIdCore(String memberId) {
182	        if (memberId == null) {
183	            return null;
184	        }
185	        int dash = memberId.indexOf('-');
186	        return dash >= 0 ? memberId.substring(0, dash) : memberId;
187	    }
188	
189	    /**
190	     * The REGION segment carried by the owner's assigned memberId: the part of its
191	     * {@link #memberIdCore core} before the fixed trailing FY(2) + HASH8(8) + CHK(1). Returns null
192	     * when no memberId has been assigned, or when it carries no region segment.
193	     */
194	    private String identityRegion(Owner owner) {
195	        String core = memberIdCore(owner.getMemberId());
196	        return core != null && core.length() > 11 ? core.substring(0, core.length() - 11) : null;
197	    }
198	
199	    /**
200	     * The owner's locality: the REGION segment of its assigned identity code (see
201	     * {@link #identityRegion}). When no code has been assigned this falls back to the canonical
202	     * region derived from the owner via {@link CityRegionResolver}, preferring the postcode over the
203	     * city, or 'UNKNOWN' when neither yields a known region.
204	     */
205	    String locality(Owner owner) {
206	        String region = identityRegion(owner);
207	        return region != null ? region : cityRegionResolver.regionFor(owner.getCity(), owner.getPostcode());
208	    }
209	
210	    /**
211	     * The owner's segment, formatted '&lt;TIER&gt;_&lt;AREA&gt;'. TIER is 'PREMIUM' when the owner's
212	     * {@link #membershipLevel(Owner) membershipLevel} is 3 or more, otherwise 'STANDARD'. AREA is
213	     * 'METRO' when the owner's {@link #locality(Owner) locality} is a known region (NSW, VIC or QLD),
214	     * otherwise 'REGIONAL'.
215	     */
216	    OwnerDto.OwnerSegmentEnum ownerSegment(Owner owner) {
217	        String tier = membershipLevel(owner) >= 3 ? "PREMIUM" : "STANDARD";
218	        boolean knownRegion = cityRegionResolver.timezoneForRegion(locality(owner)) != null;
219	        String area = knownRegion ? "METRO" : "REGIONAL";
220	        return OwnerDto.OwnerSegmentEnum.fromValue(tier + "_" + area);
221	    }
222	
223	    /**
224	     * The owner's IANA timezone name derived from the owner's {@link #locality(Owner) locality}
225	     * via the fixed region-to-timezone table (NSW -> Australia/Sydney, VIC -> Australia/Melbourne,
226	     * QLD -> Australia/Brisbane). Returns null when the locality is not a region in the table.
227	     */
228	    String timezone(Owner owner) {
229	        return cityRegionResolver.timezoneForRegion(locality(owner));
230	    }
231	
232	    /**
233	     * The owner's membership points: starting at 0, plus 2 when an email address is present,
234	     * plus 1 when namesakeCount is 0, plus 2 for a household of 3 or more members, plus 3 when
235	     * the owner's tenure is more than one fiscal year.
236	     */
237	    public int membershipPoints(Owner owner) {
238	        int points = 0;
239	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
240	        if (hasEmail) {
241	            points += 2;
242	        }
243	        boolean uniqueName = owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0;
244	        if (uniqueName) {
245	            points += 1;
246	        }
247	        if (householdSize(owner) >= 3) {
248	            points += 2;
249	        }
250	        LocalDate registrationDate = owner.getRegistrationDate();
251	        boolean tenured = registrationDate != null
252	            && fiscalYear(LocalDate.now()) - fiscalYear(registrationDate) > 1;
253	        if (tenured) {
254	            points += 3;
255	        }
256	        return points;
257	    }
258	
259	    /**
260	     * The owner's numeric membership level from 1 to 4, derived from {@link #membershipPoints}
261	     * via {@link #levelForPoints} and then held to the household level-ceiling by
262	     * {@link #cappedByHousehold}.
263	     */
264	    public int membershipLevel(Owner owner) {
265	        return cappedByHousehold(owner, levelForPoints(membershipPoints(owner)));
266	    }
267	
268	    /**
269	     * Hold {@code level} to the household level-ceiling: an owner's membershipLevel may not exceed
270	     * one above the current maximum membershipLevel among the household members that already
271	     * existed when this owner registered — the other, non-deleted owners sharing its householdId
272	     * that were created earlier (a strictly lower id, ids being monotonic). When no such earlier
273	     * household member exists no ceiling applies and {@code level} is returned unchanged.
274	     *
275	     * @param owner the owner whose own level is being capped
276	     * @param level the owner's uncapped membership level
277	     * @return the level, capped at one above the earlier household members' maximum
278	     */
279	    private int cappedByHousehold(Owner owner, int level) {
280	        Integer id = owner.getId();
281	        String householdId = owner.getHouseholdId();
282	        if (id == null || householdId == null) {
283	            return level;
284	        }
285	        OptionalInt maxExisting = clinicService.findAllOwners().stream()
286	            .filter(existing -> !existing.isDeleted())
287	            .filter(existing -> existing.getId() != null && existing.getId() < id)
288	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
289	            .mapToInt(this::membershipLevel)
290	            .max();
291	        return maxExisting.isEmpty() ? level : Math.min(level, maxExisting.getAsInt() + 1);
292	    }
293	
294	    /**
295	     * The numeric membership level from 1 to 4 that {@code points} maps to: level 1 for 0-1
296	     * points, level 2 for 2-3 points, level 3 for 4-5 points and level 4 for 6 or more points.
297	     */
298	    int levelForPoints(int points) {
299	        if (points >= 6) {
300	            return 4;
301	        }
302	        if (points >= 4) {
303	            return 3;
304	        }
305	        if (points >= 2) {
306	            return 2;
307	        }
308	        return 1;
309	    }
310	
311	    /**
312	     * The owners belonging to {@code owner}'s household, i.e. those sharing its householdId
313	     * (including the owner itself once persisted). Returns an empty list when the owner has no
314	     * household id assigned.
315	     */
316	    List<Owner> householdMembers(Owner owner) {
317	        String householdId = owner.getHouseholdId();
318	        if (householdId == null) {
319	            return List.of();
320	        }
321	        return clinicService.findAllOwners().stream()
322	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
323	            .toList();
324	    }
325	
326	    /**
327	     * The number of owners belonging to {@code owner}'s household, i.e. those sharing its
328	     * householdId (including the owner itself once persisted). Returns 0 when the owner has no
329	     * household id assigned.
330	     */
331	    int householdSize(Owner owner) {
332	        return householdMembers(owner).size();
333	    }
334	
335	    /**
336	     * The owner's salutation: the {@code title} and last name separated by a single space
337	     * (e.g. 'DR who'), or just the last name when no title has been supplied.
338	     */
339	    String salutation(Owner owner) {
340	        String title = owner.getTitle();
341	        if (title == null || title.isBlank()) {
342	            return owner.getLastName();
343	        }
344	        return title + " " + owner.getLastName();
345	    }
346	
347	    /**
348	     * The upper-cased first letters of firstName and lastName, dot-separated with a
349	     * trailing dot, e.g. 'J.S.'.
350	     */
351	    String initials(Owner owner) {
352	        return Character.toUpperCase(owner.getFirstName().charAt(0)) + "."
353	            + Character.toUpperCase(owner.getLastName().charAt(0)) + ".";
354	    }
355	
356	    public abstract Owner toOwner(OwnerDto ownerDto);
357	
358	    @Mapping(target = "id", ignore = true)
359	    @Mapping(target = "pets", ignore = true)
360	    public abstract Owner toOwner(OwnerFieldsDto ownerDto);
361	
362	    public abstract List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
363	
364	    public abstract Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
365	
366	    public OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
367	        OwnerPageDto ownerPageDto = new OwnerPageDto();
368	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
369	        ownerPageDto.setPage(ownerPage.getNumber());
370	        ownerPageDto.setSize(ownerPage.getSize());
371	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
372	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
373	        return ownerPageDto;
374	    }
375	}
