17	package org.springframework.samples.petclinic.rest.controller;
18	
19	import java.time.LocalDate;
20	import java.util.Locale;
21	import java.util.Set;
22	import java.util.regex.Pattern;
23	
24	import org.springframework.http.HttpHeaders;
25	import org.springframework.http.HttpStatus;
26	import org.springframework.http.ResponseEntity;
27	import org.springframework.samples.petclinic.mapper.OwnerMapper;
28	import org.springframework.samples.petclinic.model.Owner;
29	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
30	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
31	import org.springframework.samples.petclinic.service.ClinicService;
32	import org.springframework.samples.petclinic.util.HashUtils;
33	import org.springframework.samples.petclinic.util.IdentityUtils;
34	import org.springframework.stereotype.Component;
35	import org.springframework.web.util.UriComponentsBuilder;
36	
37	/**
38	 * Owns the owner-creation concern: the single place that turns a submitted
39	 * {@link OwnerFieldsDto} into a validated, normalized, enriched and persisted {@link Owner},
40	 * and reports the create outcome as the HTTP response the endpoint returns.
41	 *
42	 * <p>Keeping the whole create pipeline here means every rule that fires on create — the
43	 * registration-date and business-day handling, the per-day and per-city quotas, the
44	 * address/telephone/email/postcode normalization and validation, the household, duplicate
45	 * and soft-match identity rules, and the derived member id and namesake count — reads the
46	 * one owner this class builds, in the one order it applies
47	 * them, so they can never drift apart. The controller is left holding only the endpoint's
48	 * HTTP boundary.
49	 */
50	@Component
51	public class OwnerRegistrar {
52	
53	    /** Minimal syntactic check for an email address: a non-empty local part, a single
54	     *  '@', and a dotted domain, none containing whitespace or a second '@'. */
55	    private static final Pattern EMAIL_PATTERN =
56	        Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
57	
58	    /** A postcode, when supplied, must be exactly four digits before its region range is checked. */
59	    private static final Pattern POSTCODE_PATTERN = Pattern.compile("^[0-9]{4}$");
60	
61	    /** Disposable email domains that are rejected: an owner whose email domain matches one of
62	     *  these (case-insensitively) is refused with 400. */
63	    private static final java.util.Set<String> DISPOSABLE_EMAIL_DOMAINS =
64	        java.util.Set.of("mailinator.com", "tempmail.com", "guerrillamail.com");
65	
66	    private final ClinicService clinicService;
67	
68	    private final OwnerMapper ownerMapper;
69	
70	    private final TelephoneNormalizer telephoneNormalizer;
71	
72	    private final AddressNormalizer addressNormalizer;
73	
74	    private final CityRegionResolver cityRegionResolver;
75	
76	    private final HouseholdResolver householdResolver;
77	
78	    private final OwnerAuditor ownerAuditor;
79	
80	    private final WelcomeNotifier welcomeNotifier;
81	
82	    /**
83	     * Remembers, per {@code Idempotency-Key}, the id of the owner that key's create originally
84	     * produced, so a later create carrying the same key returns that same owner instead of
85	     * creating a duplicate. The registrar is a singleton, so this store outlives a single
86	     * request; entries are keyed by the client-supplied key, which is expected to be unique
87	     * per logical create.
88	     */
89	    private final java.util.concurrent.ConcurrentHashMap<String, Integer> idempotencyKeys =
90	        new java.util.concurrent.ConcurrentHashMap<>();
91	
92	    public OwnerRegistrar(ClinicService clinicService,
93	                          OwnerMapper ownerMapper,
94	                          TelephoneNormalizer telephoneNormalizer,
95	                          AddressNormalizer addressNormalizer,
96	                          CityRegionResolver cityRegionResolver,
97	                          HouseholdResolver householdResolver,
98	                          OwnerAuditor ownerAuditor,
99	                          WelcomeNotifier welcomeNotifier) {
100	        this.clinicService = clinicService;
101	        this.ownerMapper = ownerMapper;
102	        this.telephoneNormalizer = telephoneNormalizer;
103	        this.addressNormalizer = addressNormalizer;
104	        this.cityRegionResolver = cityRegionResolver;
105	        this.householdResolver = householdResolver;
106	        this.ownerAuditor = ownerAuditor;
107	        this.welcomeNotifier = welcomeNotifier;
108	    }
109	
110	    /**
111	     * Validate, normalize, enrich and persist a new owner from the submitted fields, and
112	     * report the outcome as the response the create endpoint returns: {@code 201 Created}
113	     * (with a {@code Location} header and the created owner) on success, or the appropriate
114	     * rejection status ({@code 400}, {@code 409} or {@code 429}) when a create rule refuses
115	     * the request. No owner is persisted unless every rule passes.
116	     *
117	     * @param ownerFieldsDto the submitted owner fields
118	     * @return the create outcome as an HTTP response
119	     */
120	    public ResponseEntity<OwnerDto> register(OwnerFieldsDto ownerFieldsDto) {
121	        return register(ownerFieldsDto, null);
122	    }
123	
124	    /**
125	     * As {@link #register(OwnerFieldsDto)}, but honouring an optional {@code Idempotency-Key}.
126	     * When {@code idempotencyKey} is non-blank and a create with that key has already succeeded,
127	     * the owner it originally produced is returned with {@code 200 OK} instead of creating a
128	     * duplicate. Otherwise the normal create pipeline runs and, on success, the key is recorded
129	     * against the created owner so a later repeat resolves to the same owner.
130	     *
131	     * @param ownerFieldsDto the submitted owner fields
132	     * @param idempotencyKey the request's {@code Idempotency-Key} header, or {@code null} when absent
133	     * @return the create outcome as an HTTP response
134	     */
135	    public ResponseEntity<OwnerDto> register(OwnerFieldsDto ownerFieldsDto, String idempotencyKey) {
136	        String key = (idempotencyKey == null || idempotencyKey.isBlank()) ? null : idempotencyKey.trim();
137	        if (key != null) {
138	            Integer existingId = idempotencyKeys.get(key);
139	            if (existingId != null) {
140	                Owner original = this.clinicService.findOwnerById(existingId);
141	                if (original != null) {
142	                    return new ResponseEntity<>(ownerMapper.toOwnerDto(original), HttpStatus.OK);
143	                }
144	                // The originally created owner is gone; forget the stale key and create afresh.
145	                idempotencyKeys.remove(key);
146	            }
147	        }
148	        HttpHeaders headers = new HttpHeaders();
149	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
150	        if (owner.getRegistrationDate() == null) {
151	            owner.setRegistrationDate(LocalDate.now());
152	        }
153	        // A supplied registration date may not be later than the server's current date.
154	        if (owner.getRegistrationDate().isAfter(LocalDate.now())) {
155	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
156	        }
157	        owner.setRegistrationDate(toBusinessDay(owner.getRegistrationDate()));
158	        LocalDate registrationDate = owner.getRegistrationDate();
159	        long ownersCreatedThatDay = this.clinicService.findAllOwners().stream()
160	            .map(Owner::getRegistrationDate)
161	            .filter(registrationDate::equals)
162	            .count();
163	        if (ownersCreatedThatDay >= 100) {
164	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
165	        }
166	        String address = normalizedAddress(owner);
167	        if (address == null) {
168	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
169	        }
170	        owner.setAddress(address);
171	        String telephone = telephoneNormalizer.normalize(owner.getTelephone());
172	        if (telephone == null) {
173	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
174	        }
175	        if (!telephoneNormalizer.hasValidNationalNumberLength(telephone)) {
176	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
177	        }
178	        owner.setTelephone(telephone);
179	        String email = owner.getEmail();
180	        if (email != null) {
181	            email = email.trim();
182	            if (!EMAIL_PATTERN.matcher(email).matches()) {
183	                return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
184	            }
185	            String domain = email.substring(email.indexOf('@') + 1).toLowerCase(Locale.ROOT);
186	            if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
187	                return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
188	            }
189	            owner.setEmail(email.toLowerCase(Locale.ROOT));
190	        }
191	        // A postcode is optional, but when supplied it must be four digits and valid for the
192	        // owner's city per the fixed region table; a city with no known region accepts any
193	        // 4-digit postcode. Reject an out-of-range or malformed postcode with 400.
194	        String postcode = owner.getPostcode();
195	        if (postcode != null) {
196	            if (!POSTCODE_PATTERN.matcher(postcode).matches()
197	                    || !cityRegionResolver.isPostcodeValidForCity(owner.getCity(), postcode)) {
198	                return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
199	            }
200	        }
201	        // The owner's telephone and email are now in their canonical, stored form.
202	        // The household id is deterministic: owners with the same normalized last name and
203	        // postcode share it automatically. Assign it unconditionally so the membership-level
204	        // ceiling can key off it; it no longer participates in duplicate detection, which now
205	        // rests solely on the identity key below.
206	        owner.setHouseholdId(householdResolver.householdId(owner));
207	        // Duplicate detection is the single identity key: a candidate is rejected only when its
208	        // whole identityKey (normalized telephone, lower-cased email and soundex of the last name)
209	        // collides with a non-deleted owner's. Two people sharing a household with different
210	        // telephones therefore derive different keys and are both admitted; the second is instead
211	        // flagged as a possible duplicate by the soft-match rule below.
212	        if (isDuplicateOwner(owner)) {
213	            return new ResponseEntity<>(HttpStatus.CONFLICT);
214	        }
215	        String cityKey = IdentityUtils.normalizeIdentity(owner.getCity());
216	        long ownersInCity = this.clinicService.findAllOwners().stream()
217	            .filter(existing -> IdentityUtils.normalizeIdentity(existing.getCity()).equals(cityKey))
218	            .count();
219	        if (ownersInCity >= 50) {
220	            return new ResponseEntity<>(HttpStatus.CONFLICT);
221	        }
222	        // Approaching-capacity warning: the city already holds 40-49 owners (the hard limit is 50,
223	        // rejected above). ownersInCity counts the existing owners the candidate is joining.
224	        owner.setCapacityWarning(ownersInCity >= 40 && ownersInCity < 50);
225	        owner.setMemberId(memberId(owner));
226	        owner.setNamesakeCount(namesakeCount(owner));
227	        owner.setBulkSignupWarning(ownersCreatedThatDay > 80);
228	        // Soft-match: the candidate has already cleared the hard-duplicate check, but its
229	        // identityKey may still differ from an existing owner's while their last names sound alike
230	        // (equal soundex) and their postcodes match — a likely re-registration of the same person
231	        // under a different telephone or email. When it does, it is created but flagged as a
232	        // possible duplicate of that existing owner; otherwise the flag is false and no reference
233	        // is recorded.
234	        Integer possibleDuplicateOf = possibleDuplicateOf(owner);
235	        owner.setPossibleDuplicate(possibleDuplicateOf != null);
236	        owner.setPossibleDuplicateOf(possibleDuplicateOf);
237	        this.clinicService.saveOwner(owner);
238	        if (key != null) {
239	            idempotencyKeys.put(key, owner.getId());
240	        }
241	        ownerAuditor.ownerCreated(owner, ownerMapper.membershipLevel(owner));
242	        welcomeNotifier.welcome(owner);
243	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
244	        headers.setLocation(UriComponentsBuilder.newInstance()
245	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
246	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
247	    }
248	
249	    /**
250	     * The owner's postal address in the single canonical form under which it is stored, or
251	     * {@code null} when the owner supplies no usable address. An owner may supply its address
252	     * in EITHER form: the structured {@code addressLine1} (with an optional {@code addressLine2})
253	     * is preferred, and the flat {@code address} remains accepted for backward compatibility.
254	     *
255	     * <p>Normalization by {@link AddressNormalizer} is applied to whichever fields are supplied.
256	     * When a non-blank {@code addressLine1} is present the owner's structured fields are replaced
257	     * with their normalized values (a blank or absent {@code addressLine2} is cleared to
258	     * {@code null}) and the returned address is composed as the normalized {@code addressLine1},
259	     * with a single space and the normalized {@code addressLine2} appended when present. Otherwise
260	     * the flat {@code address} is normalized and the structured fields are cleared. A blank result
261	     * (no usable address in either form) has no canonical form and is reported as {@code null} so
262	     * the caller can reject the request with 400.
263	     *
264	     * <p>This is the single point at which an owner's address is resolved and normalized on
265	     * create, so every rule keyed on the stored address reads the one value produced here.
266	     *
267	     * @param owner the owner about to be created
268	     * @return the canonical stored address, or {@code null} when the owner supplies none
269	     */
270	    private String normalizedAddress(Owner owner) {
271	        String rawLine1 = owner.getAddressLine1();
272	        if (rawLine1 != null && !rawLine1.isBlank()) {
273	            String line1 = addressNormalizer.normalize(rawLine1);
274	            String line2 = addressNormalizer.normalize(owner.getAddressLine2());
275	            owner.setAddressLine1(line1);
276	            owner.setAddressLine2(line2.isBlank() ? null : line2);
277	            return line2.isBlank() ? line1 : line1 + " " + line2;
278	        }
279	        owner.setAddressLine1(null);
280	        owner.setAddressLine2(null);
281	        String address = addressNormalizer.normalize(owner.getAddress());
282	        return address.isBlank() ? null : address;
283	    }
284	
285	    /**
286	     * Whether {@code candidate} collides with an already-registered owner under the single
287	     * identity rule enforced on create. This is the one point at which a new owner is
288	     * rejected as a duplicate (HTTP 409): all duplicate detection is consolidated into the
289	     * derived {@link OwnerMapper#identityKey identityKey} — the SHA-256 hex over the normalized
290	     * telephone, the lower-cased email (or an empty string when absent) and the soundex of the
291	     * last name, joined by '|'. The candidate clashes only when its WHOLE identityKey equals an
292	     * existing owner's; because the telephone is part of the key, two people sharing a household
293	     * (a like-sounding last name and postcode) with different telephones have different
294	     * identityKeys and are both allowed.
295	     *
296	     * <p>The candidate arrives with its telephone and email already normalized, and each existing
297	     * owner is stored in the same canonical form, so an identityKey match means the two owners are
298	     * genuinely the same identity.
299	     *
300	     * @param candidate the fully-normalized owner about to be created
301	     * @return {@code true} if an existing owner already occupies the candidate's identityKey
302	     */
303	    private boolean isDuplicateOwner(Owner candidate) {
304	        String identityKey = OwnerMapper.identityKey(candidate);
305	        return this.clinicService.findAllOwners().stream()
306	            .filter(existing -> !existing.isDeleted())
307	            .map(OwnerMapper::identityKey)
308	            .anyMatch(identityKey::equals);
309	    }
310	
311	    /**
312	     * The id of the existing owner the fully-normalized {@code candidate} soft-matches, or
313	     * {@code null} when there is none. A soft match is an owner whose whole identityKey differs
314	     * from the candidate's (so it is not a hard duplicate) yet whose last name sounds alike (equal
315	     * {@link IdentityUtils#soundex soundex}) and whose postcode matches — a likely re-registration
316	     * of the same person under a different telephone or email. Both must supply a postcode for a
317	     * match to be possible; when several existing owners qualify the lowest id is returned so the
318	     * result is deterministic.
319	     *
320	     * @param candidate the fully-normalized owner about to be created
321	     * @return the matching existing owner's id, or {@code null} if the candidate is no soft match
322	     */
323	    private Integer possibleDuplicateOf(Owner candidate) {
324	        String postcode = candidate.getPostcode();
325	        if (postcode == null || postcode.isBlank()) {
326	            return null;
327	        }
328	        String identityKey = OwnerMapper.identityKey(candidate);
329	        String lastNameSoundex = IdentityUtils.soundex(candidate.getLastName());
330	        return this.clinicService.findAllOwners().stream()
331	            .filter(existing -> !existing.isDeleted()
332	                && !identityKey.equals(OwnerMapper.identityKey(existing))
333	                && IdentityUtils.soundex(existing.getLastName()).equals(lastNameSoundex)
334	                && postcode.equals(existing.getPostcode()))
335	            .map(Owner::getId)
336	            .filter(java.util.Objects::nonNull)
337	            .min(Integer::compareTo)
338	            .orElse(null);
339	    }
340	
341	    /**
342	     * Build the member id assigned to {@code owner} on create, formatted
343	     * {@code '<REGION><FY><HASH8><CHK>'}: REGION is the region code derived from the owner's
344	     * postcode (falling back to the city) via {@link CityRegionResolver}, FY is the two-digit
345	     * fiscal year of the (business-day-adjusted) registrationDate (the fiscal year starts on
346	     * 1 July), HASH8 is the first eight upper-case hex characters of the SHA-256 digest of the
347	     * normalized telephone concatenated with the last name (the same HASH8 used by the
348	     * region-and-hash identity), and CHK is a single Luhn check digit computed over the digits
349	     * of {@code '<REGION><FY><HASH8>'} (e.g. 'NSW261A2B3C4D5').
350	     *
351	     * <p>When the computed id collides with an already-registered owner's memberId it is
352	     * de-duplicated by appending {@code '-<n>'} with the smallest {@code n} of 2 or more that
353	     * makes it unique (e.g. 'NSW261A2B3C4D5-2'), and the unique id is returned.
354	     */
355	    private String memberId(Owner owner) {
356	        String region = cityRegionResolver.regionFor(owner.getCity(), owner.getPostcode());
357	        String fy = String.format("%02d", OwnerMapper.fiscalYear(owner.getRegistrationDate()) % 100);
358	        String hash8 = HashUtils.sha256HexPrefix(owner.getTelephone() + owner.getLastName(), 8);
359	        String core = region + fy + hash8;
360	        String base = core + OwnerMapper.luhn(core);
361	        java.util.Set<String> existing = this.clinicService.findAllOwners().stream()
362	            .map(Owner::getMemberId)
363	            .filter(java.util.Objects::nonNull)
364	            .collect(java.util.stream.Collectors.toSet());
365	        return disambiguate(base, existing);
366	    }
367	
368	    /**
369	     * Make {@code base} unique among the {@code existing} identity codes: return it unchanged when
370	     * it is free, otherwise append {@code '-<n>'} with the smallest {@code n} of 2 or more that is
371	     * not already taken (e.g. 'NSW-1A2B3C4D-2'). This is the single de-duplication step an assigned
372	     * identity code passes through, so a collision is broken the one way wherever a code is built.
373	     */
374	    private static String disambiguate(String base, java.util.Set<String> existing) {
375	        if (!existing.contains(base)) {
376	            return base;
377	        }
378	        int n = 2;
379	        while (existing.contains(base + "-" + n)) {
380	            n++;
381	        }
382	        return base + "-" + n;
383	    }
384	
385	    /**
386	     * The number of existing owners that share {@code owner}'s firstName and lastName,
387	     * compared case-insensitively. The candidate is not yet stored at the point this is
388	     * assigned, so it does not count itself. This is the value stored as the owner's
389	     * namesakeCount on create.
390	     */
391	    private int namesakeCount(Owner owner) {
392	        return (int) this.clinicService.findAllOwners().stream()
393	            .filter(existing -> owner.getFirstName().equalsIgnoreCase(existing.getFirstName())
394	                && owner.getLastName().equalsIgnoreCase(existing.getLastName()))
395	            .count();
396	    }
397	
398	    /** Fixed list of public holidays that a registration date must roll past. */
399	    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
400	        LocalDate.of(2026, 1, 1),
401	        LocalDate.of(2026, 1, 26),
402	        LocalDate.of(2026, 4, 25),
403	        LocalDate.of(2026, 12, 25),
404	        LocalDate.of(2026, 12, 28));
405	
406	    /**
407	     * Roll a registration date forward to the next business day: a Saturday, Sunday
408	     * or listed public holiday advances one day at a time until it lands on a weekday
409	     * that is not a public holiday. A plain weekday is returned unchanged.
410	     */
411	    private static LocalDate toBusinessDay(LocalDate date) {
412	        while (isWeekend(date) || PUBLIC_HOLIDAYS.contains(date)) {
413	            date = date.plusDays(1);
414	        }
415	        return date;
416	    }
417	
418	    private static boolean isWeekend(LocalDate date) {
419	        return switch (date.getDayOfWeek()) {
420	            case SATURDAY, SUNDAY -> true;
421	            default -> false;
422	        };
423	    }
424	}
